import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"思忠","description":"","frontmatter":{"title":"思忠","date":"2026-11-24T00:00:00.000Z","seq":45,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"王褒","source_book":"楚辞","prev":{"text":"蓄英","link":"/blogs/楚辞/蓄英.html"},"next":{"text":"陶壅","link":"/blogs/楚辞/陶壅.html"}},"headers":[],"relativePath":"blogs/楚辞/思忠.md","filePath":"blogs/楚辞/思忠.md"}'),o={name:"blogs/楚辞/思忠.md"};function l(n,a,c,m,r,_){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="思忠" tabindex="-1">思忠 <a class="header-anchor" href="#思忠" aria-label="Permalink to &quot;思忠&quot;">​</a></h1><p class="poem-meta">先秦 · 王褒　·　九怀</p><div class="poem"><p class="poem-stanza">登九灵兮游神，静女歌兮微晨。</p><p class="poem-stanza">悲皇丘兮积葛，众体错兮交纷。</p><p class="poem-stanza">贞枝抑兮枯槁，枉车登兮庆云。</p><p class="poem-stanza">感余志兮惨栗，心怆怆兮自怜。</p><p class="poem-stanza">驾玄螭兮北征，曏吾路兮葱岭。</p><p class="poem-stanza">连五宿兮建旄，扬氛气兮为旌。</p><p class="poem-stanza">历广漠兮驰骛，览中国兮冥冥。</p><p class="poem-stanza">玄武步兮水母，与吾期兮南荣。</p><p class="poem-stanza">登华盖兮乘阳，聊逍遥兮播光。</p><p class="poem-stanza">抽库娄兮酌醴，援瓟瓜兮接粮。</p><p class="poem-stanza">毕休息兮远逝，发玉軔兮西行。</p><p class="poem-stanza">惟时俗兮疾正，弗可久兮此方。</p><p class="poem-stanza">寤辟摽兮永思，心怫郁兮内伤。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
